<?php
namespace RobwForge;
defined('ABSPATH') || exit;
final class HTTP {
 static function response($s,$code=200,$type='application/json'){status_header($code);header('Content-Type: '.$type);header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');echo$type==='application/json'?wp_json_encode($s):$s;exit;}
 static function cookie(){if(!is_user_logged_in()||!current_user_can('read'))throw new \RuntimeException('Login required',401);return get_current_user_id();}
 static function form(){if(!wp_verify_nonce($_POST['_wpnonce']??$_SERVER['HTTP_X_WP_NONCE']??'','robw-forge'))throw new \RuntimeException('Invalid nonce',403);}
 static function route(){ $path=wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$base=rtrim(wp_parse_url(home_url(),PHP_URL_PATH)??'','/');if(str_starts_with($path,$base.'/wp-content/uploads/robw-forge/'))self::response(['error'=>'Not found'],404);if(!str_starts_with($path,$base.'/forge'))return;$path=substr($path,strlen($base));if($path!=='/forge'&&!str_starts_with($path,'/forge/'))return;try{if(!is_ssl()&&!Hooks::local())throw new \RuntimeException('HTTPS required',400);
 if($path==='/forge'||$path==='/forge/'){if($_SERVER['REQUEST_METHOD']==='POST'){self::form();$uid=self::cookie();$id=$_POST['repo']??'';$data=wp_unslash($_POST);if(($data['op']??'')==='create')$result=Store::create($id,$uid);elseif(($data['op']??'')==='deliver'){[$raw,$r]=Store::read($id);Store::owner($r,$uid);$result=['delivered'=>Hooks::deliver($id)];}else$result=Store::manage($id,$uid,$data);header('Content-Type: text/html; charset=utf-8');echo '<p>Saved.</p>';if(isset($result['secret']))echo '<p>Webhook secret (shown once): <code>'.esc_html($result['secret']).'</code></p>';echo '<a href="'.esc_url(home_url('/forge?repo='.$id)).'">Continue</a>';exit;}self::page();exit;}
 if(preg_match('~^/forge/api/([a-z0-9][a-z0-9-]{0,62})$~D',$path,$m)){$uid=self::cookie();$id=$m[1];if($_SERVER['REQUEST_METHOD']==='GET'){[$raw,$r]=Store::read($id);Store::require_access($r,$uid);self::response(Store::overview($r,$uid));}if($_SERVER['REQUEST_METHOD']!=='POST')throw new \RuntimeException('Method not allowed',405);self::form();$raw=file_get_contents('php://input',false,null,0,16385);if(strlen($raw)>16384)throw new \RuntimeException('Request quota',413);$data=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(!is_array($data))throw new \InvalidArgumentException('Invalid JSON');foreach($data as$k=>$v)if(!is_string($v))throw new \InvalidArgumentException('Invalid input');if(($data['op']??'')==='create')self::response(Store::create($id,$uid),201);if(($data['op']??'')==='deliver'){[$old,$r]=Store::read($id);Store::owner($r,$uid);self::response(['processed'=>Hooks::deliver($id)]);}self::response(Store::manage($id,$uid,$data));}
 if(!preg_match('~^/forge/git/([a-z0-9][a-z0-9-]{0,62})\.git/(info/refs|git-upload-pack|git-receive-pack)$~D',$path,$m))throw new \RuntimeException('Not found',404);if(!function_exists('robw_oauth_principal'))throw new \RuntimeException('OAuth provider required',503);$id=$m[1];$op=$m[2];$get=$op==='info/refs';$service=$get?($_GET['service']??''):$op;if(!in_array($service,['git-upload-pack','git-receive-pack'],true)||($get&&$_SERVER['QUERY_STRING']!=='service='.$service)||(!$get&&!empty($_SERVER['QUERY_STRING'])))throw new \RuntimeException('Unsupported service',400);if($_SERVER['REQUEST_METHOD']!==($get?'GET':'POST'))throw new \RuntimeException('Method not allowed',405);$write=$service==='git-receive-pack';$auth=robw_oauth_principal($_SERVER['HTTP_AUTHORIZATION']??'','robw-forge/'.$id,$write);if(is_wp_error($auth)){header('WWW-Authenticate: Basic realm="Git Forge"');throw new \RuntimeException('Git access denied',$auth->get_error_data()['status']);}$uid=$auth['user_id'];[$raw,$r]=Store::read($id);Store::require_access($r,$uid,$write);if($get)self::response(Git::advertise($r,$service),200,'application/x-'.$service.'-advertisement');if(strtolower($_SERVER['CONTENT_TYPE']??'')!=='application/x-'.$service.'-request')throw new \RuntimeException('Git content type',415);if(isset($_SERVER['HTTP_CONTENT_ENCODING'])||isset($_SERVER['CONTENT_ENCODING']))throw new \RuntimeException('Encoding unsupported',415);$body=file_get_contents('php://input',false,null,0,Git::PACK+65537);if(strlen($body)>Git::PACK+65536)throw new \RuntimeException('Request quota',413);if(!$write)self::response(Git::fetch($r,$body),200,'application/x-git-upload-pack-result');[$commands,$pack]=Git::commands($body);$new=Git::unpack($pack,$r['objects']);Store::push($id,$uid,$commands,$new);$out=Git::pkt("unpack ok\n");foreach($commands as$ref=>$v)$out.=Git::pkt('ok '.$ref."\n");self::response($out.'0000',200,'application/x-git-receive-pack-result');
 }catch(\InvalidArgumentException|\JsonException $e){if(Hooks::local())error_log('Forge rejection: '.$e->getMessage());self::response(['error'=>$e->getMessage()],400);}catch(\Throwable $e){$code=in_array($e->getCode(),[400,401,403,404,405,409,413,415,503],true)?$e->getCode():503;self::response(['error'=>$e->getMessage()],$code);}}
 static function admin(){echo '<div class="wrap"><h1>Git Forge</h1><p>Repository management and browsing: <a href="'.esc_url(home_url('/forge')).'">open forge</a>.</p><p>The separate Robw OAuth plugin manages clients, consent and tokens. This plugin owns Git data, permissions, issues and webhook delivery.</p></div>';}
 static function page(){if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/forge')));exit;}$uid=self::cookie();header('Content-Type: text/html; charset=utf-8');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");echo '<!doctype html><title>Git Forge</title><style>body{max-width:1000px;margin:2em auto;font-family:system-ui}pre{white-space:pre-wrap;overflow-wrap:anywhere}input,textarea{margin:.4em}fieldset{margin:1em 0}</style><h1>Git Forge</h1><p><a href="'.esc_url(home_url('/forge')).'">Projects</a> · Authentication is provided by the separate Robw OAuth plugin.</p>';
 $id=$_GET['repo']??'';if(!$id){echo '<ul>';foreach(Store::list_ids()as$i){[$raw,$r]=Store::read($i);if(Store::allowed($r,$uid))echo '<li><a href="'.esc_url(home_url('/forge?repo='.$i)).'">'.esc_html($i).'</a></li>';}echo '</ul>';if(current_user_can('edit_posts'))self::form_html('', 'create','Create repository',['repo'=>'']);return;}
 [$raw,$r]=Store::read($id);Store::require_access($r,$uid);echo '<h2>'.esc_html($id).'</h2><p>Private HTTPS Git URL: <code>'.esc_html(home_url('/forge/git/'.$id.'.git')).'</code></p><p><a href="'.esc_url(home_url('/forge?repo='.$id.'&view=log')).'">Commits</a></p><ul>';foreach($r['refs']as$ref=>$oid)echo '<li>'.esc_html($ref).' <a href="'.esc_url(add_query_arg(['repo'=>$id,'oid'=>$oid,'view'=>'tree'],home_url('/forge'))).'">'.esc_html(substr($oid,0,12)).'</a></li>';echo '</ul>';
 $oid=$_GET['oid']??($r['refs']['refs/heads/main']??null);$view=$_GET['view']??'tree';if($oid){$allowed=Git::closure($r['objects'],$r['refs']);if(!isset($allowed[$oid]))throw new \RuntimeException('Object not found',404);[$t,$d]=Git::get($allowed,$oid);if($view==='log'&&$t==='commit'){$todo=[$oid];$seen=[];$n=0;while($todo&&$n<100){$o=array_pop($todo);if(isset($seen[$o]))continue;$seen[$o]=true;$n++;[$ct,$cd]=Git::get($allowed,$o);echo '<article><h3>'.esc_html(substr($o,0,12)).'</h3><pre>'.esc_html($cd).'</pre></article>';foreach(Git::links($ct,$cd)as$next=>$type)if($type==='commit')$todo[]=$next;}}else{if($t==='commit'){$links=Git::links($t,$d);$oid=array_key_first($links);[$t,$d]=Git::get($allowed,$oid);}if($t==='tree'){echo '<ul>';foreach(Git::tree($d)as$name=>$e){echo '<li>';if($e['mode']==='160000')echo esc_html($name.' (submodule '.$e['oid'].')');else echo '<a href="'.esc_url(add_query_arg(['repo'=>$id,'oid'=>$e['oid']],home_url('/forge'))).'">'.esc_html($name).'</a>';echo '</li>';}echo '</ul>';}else echo '<pre id="forge-object">'.esc_html($d).'</pre>';}}
 echo '<h2>Issues</h2>';foreach($r['issues']as$n=>$issue){echo '<article><h3>#'.esc_html($n).' '.esc_html($issue['title']).' ('.($issue['open']?'open':'closed').')</h3><pre>'.esc_html($issue['body']).'</pre>';foreach($issue['comments']as$c)echo '<pre>'.esc_html($c['body']).'</pre>';if(Store::allowed($r,$uid,true)){self::form_html($id,'comment','Comment',['issue'=>$n,'body'=>'']);self::form_html($id,$issue['open']?'close':'reopen',$issue['open']?'Close issue':'Reopen issue',['issue'=>$n]);}echo '</article>';}
 if(Store::allowed($r,$uid,true))self::form_html($id,'issue','New issue',['title'=>'','body'=>'']);if((int)$r['owner']===$uid){self::form_html($id,'member','Membership (read/write/remove)',['login'=>'','role'=>'read']);self::form_html($id,'hook','Add webhook (secret shown once)',['url'=>'']);foreach($r['hooks']as$hid=>$h){echo '<p>'.esc_html($h['url']).'</p>';self::form_html($id,'delete-hook','Remove webhook',['id'=>$hid]);}self::form_html($id,'deliver','Deliver next due webhook',[]);echo '<h3>Webhook delivery log</h3><pre>'.esc_html(wp_json_encode($r['events'],JSON_PRETTY_PRINT)).'</pre>';}}
 static function form_html($id,$op,$label,$fields){echo '<fieldset><legend>'.esc_html($label).'</legend><form method="post" action="'.esc_url(home_url('/forge')).'">';wp_nonce_field('robw-forge');echo '<input type="hidden" name="repo" value="'.esc_attr($id).'"><input type="hidden" name="op" value="'.esc_attr($op).'">';foreach($fields as$k=>$v)echo '<label>'.esc_html($k).' <input name="'.esc_attr($k).'" value="'.esc_attr($v).'"></label>';echo '<button>'.esc_html($label).'</button></form></fieldset>';}
}
